def remap(c):
    orders=list(c['catalogue'].values());indices=sorted(range(20),key=lambda i:hashlib.sha256(f'v31|42|1|train|{c["case_id"]}|{i}'.encode()).hexdigest());gold={o['drug_name'] for o in c['gold']}
